import sys

def daily_brute(t):
    n = len(t)
    res = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if t[j] > t[i]:
                res[i] = j - i
                break
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    t = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, daily_brute(t))))

import sys

def daily_best(t):
    n = len(t)
    res = [0] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and t[stack[-1]] <= t[i]:
            stack.pop()
        if stack:
            res[i] = stack[-1] - i
        stack.append(i)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    t = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, daily_best(t))))
